def find_kth_largest(nums, k):
    def qs(a, lo, hi, target):
        pivot = a[hi]
        l, m, r = lo, lo, hi
        while m <= r:
            if a[m] > pivot:
                a[l], a[m] = a[m], a[l]; l += 1; m += 1
            elif a[m] < pivot:
                a[m], a[r] = a[r], a[m]; r -= 1
            else:
                m += 1
        if target < l:
            return qs(a, lo, l-1, target)
        if target > r:
            return qs(a, r+1, hi, target)
        return a[target]
    return qs(nums, 0, len(nums)-1, k-1)

import heapq
class MedianFinder:
    def __init__(self):
        self.lo = []  # max-heap (neg)
        self.hi = []  # min-heap
    def addNum(self, x):
        heapq.heappush(self.lo, -x)
        heapq.heappush(self.hi, -heapq.heappop(self.lo))
        if len(self.hi) > len(self.lo):
            heapq.heappush(self.lo, -heapq.heappop(self.hi))
    def findMedian(self):
        if len(self.lo) > len(self.hi):
            return -self.lo[0]
        return (-self.lo[0] + self.hi[0]) / 2

