def top_k_frequent(nums, k):
    cnt = {}
    for x in nums:
        cnt[x] = cnt.get(x, 0) + 1
    buckets = [[] for _ in range(len(nums)+1)]
    for x, f in cnt.items():
        buckets[f].append(x)
    res = []
    for f in range(len(buckets)-1, 0, -1):
        for x in buckets[f]:
            res.append(x)
            if len(res) == k: return res
    return res

def top_k_frequent_sort(nums, k):
    cnt = {}
    for x in nums:
        cnt[x] = cnt.get(x, 0) + 1
    pairs = sorted(cnt.items(), key=lambda kv: -kv[1])
    return [kv[0] for kv in pairs[:k]]

