def find_maximized_capital(k, w, profits, capital):
    proj = sorted(zip(capital, profits))
    i = 0; avail = []
    for _ in range(k):
        while i < len(proj) and proj[i][0] <= w:
            heapq.heappush(avail, -proj[i][1]); i += 1
        if not avail: break
        w += -heapq.heappop(avail)
    return w

def least_interval(tasks, n):
    import heapq
    cnt = {}
    for t in tasks:
        cnt[t] = cnt.get(t, 0) + 1
    h = [-c for c in cnt.values()]
    heapq.heapify(h)
    time = 0
    while h:
        cycle = n + 1
        tmp = []
        for _ in range(cycle):
            if h:
                c = heapq.heappop(h)
                if c < -1:
                    tmp.append(c + 1)
            time += 1
            if not h and not tmp:
                break
        for c in tmp:
            heapq.heappush(h, c)
    return time

def least_interval_greedy(tasks, n):
    from collections import Counter
    cnt = Counter(tasks)
    maxf = max(cnt.values())
    num_max = sum(1 for f in cnt.values() if f == maxf)
    return max(len(tasks), (maxf - 1) * (n + 1) + num_max)

import heapq
def kth_largest_stream(k, nums, adds):
    h = nums[:]
    heapq.heapify(h)
    while len(h) > k:
        heapq.heappop(h)
    out = []
    for v in adds:
        heapq.heappush(h, v)
        if len(h) > k:
            heapq.heappop(h)
        out.append(h[0])
    return out

def k_closest(points, k):
    import heapq
    h = []
    for x, y in points:
        d = x*x + y*y
        heapq.heappush(h, (-d, x, y))
        if len(h) > k:
            heapq.heappop(h)
    return [[x, y] for _, x, y in h]

def last_stone_weight(stones):
    import heapq
    h = [-s for s in stones]
    heapq.heapify(h)
    while len(h) > 1:
        a = -heapq.heappop(h)
        b = -heapq.heappop(h)
        if a != b:
            heapq.heappush(h, -(a - b))
    return -h[0] if h else 0

def last_stone_weight_repeat(stones):
    a = stones[:]
    while len(a) > 1:
        a.sort()
        x = a.pop(); y = a.pop()
        if x != y:
            a.append(x - y)
    return a[0] if a else 0
